def bookRoom(roomId: Long) = Action { implicit request =>
  val stay = parseStay(request)
  DB.withTransaction { implicit c =>                 // commit on success, rollback on throw
    val room = SQL"SELECT * FROM rooms WHERE id = $roomId FOR UPDATE".as(roomParser.single)
    if (!room.isFree(stay)) throw new NotAvailable(roomId)
    SQL"INSERT INTO bookings (room_id, from_, to_) VALUES ($roomId, ${stay.from}, ${stay.to})"
      .executeInsert()
  }
  Ok(Json.obj("status" -> "booked"))
}

